import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.B0p3fmqd.js";const p=JSON.parse('{"title":"Common issues","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/common-issues.md","filePath":"troubleshooting/common-issues.md","lastUpdated":1791036569000}'),r={name:"troubleshooting/common-issues.md"};function i(n,e,d,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="common-issues" tabindex="-1">Common issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common issues&quot;">​</a></h1><h2 id="the-script-does-not-start" tabindex="-1">The script does not start <a class="header-anchor" href="#the-script-does-not-start" aria-label="Permalink to &quot;The script does not start&quot;">​</a></h2><ul><li>Check that <code>community_bridge</code>, <code>ox_lib</code> and <code>oxmysql</code> are started <strong>before</strong> the script.</li><li>Make sure the resource folder name matches the name in your <code>ensure</code> line.</li><li>Read the first red line in the server console. It usually names the missing dependency.</li></ul><h2 id="tables-are-missing-or-sql-errors-appear" tabindex="-1">Tables are missing or SQL errors appear <a class="header-anchor" href="#tables-are-missing-or-sql-errors-appear" aria-label="Permalink to &quot;Tables are missing or SQL errors appear&quot;">​</a></h2><p>Each script creates its own tables on first start, so there is no SQL file to import. Make sure the database user has permission to create tables, then restart the server.</p><h2 id="the-setup-command-says-i-do-not-have-permission" tabindex="-1">The setup command says I do not have permission <a class="header-anchor" href="#the-setup-command-says-i-do-not-have-permission" aria-label="Permalink to &quot;The setup command says I do not have permission&quot;">​</a></h2><p>Add the permission from the script&#39;s installation page to your permissions cfg and restart. Admin commands are locked behind an ace.</p><h2 id="an-item-has-no-icon-or-does-not-exist" tabindex="-1">An item has no icon or does not exist <a class="header-anchor" href="#an-item-has-no-icon-or-does-not-exist" aria-label="Permalink to &quot;An item has no icon or does not exist&quot;">​</a></h2><p>Add the items listed on the script&#39;s installation page to your inventory, and copy the icons into your inventory&#39;s images folder. Item names must match exactly.</p><h2 id="targets-or-zones-are-hard-to-see" tabindex="-1">Targets or zones are hard to see <a class="header-anchor" href="#targets-or-zones-are-hard-to-see" aria-label="Permalink to &quot;Targets or zones are hard to see&quot;">​</a></h2><p>Set <code>Config.Debug = true</code> in the script&#39;s config to draw the zones and print what the script is doing. Turn it back off on a live server.</p><h2 id="my-edits-were-lost-after-an-update" tabindex="-1">My edits were lost after an update <a class="header-anchor" href="#my-edits-were-lost-after-an-update" aria-label="Permalink to &quot;My edits were lost after an update&quot;">​</a></h2><p>Only the config files listed on each script&#39;s configuration page are kept open for editing. Edits to any other file are overwritten when you update.</p>',13)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
